class Solution {
public:
    int addRungs(vector<int>& rungs, int dist) {
        int curr = 0;
        int ans = 0;
        for (int r : rungs) {
            int diff = r - curr;
            if (diff > dist) ans += (diff - 1) / dist;
            curr = r;
        }
        return ans;
    }
};

class Solution {
    public int addRungs(int[] rungs, int dist) {
        int curr = 0;
        int ans = 0;
        for (int r : rungs) {
            int diff = r - curr;
            if (diff > dist) ans += (diff - 1) / dist;
            curr = r;
