    }
}

var addRungs = function(rungs, dist) {
  let curr = 0;
  let ans = 0;
  for (const r of rungs) {
    const diff = r - curr;
    if (diff > dist) ans += Math.floor((diff - 1) / dist);
    curr = r;
  }
  return ans;
};
